package dev.mcpmcp.forge;
import com.google.gson.*;import dev.mcpmcp.core.*;
import net.minecraft.client.Minecraft;import net.minecraft.core.*;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.network.protocol.game.*;import net.minecraft.network.protocol.Packet;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.InteractionHand;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.inventory.*;import net.minecraft.world.item.*;import net.minecraft.world.level.ClipContext;import net.minecraft.world.phys.*;import net.minecraftforge.common.ForgeMod;
import java.util.*;
/** Version-specific actions. Every call runs on the client thread. */
public final class Actions {
 private static boolean movementOwned;private static Boolean oldSneak;public static BlockPos lastOpenedPosition;
 public static String transport(String action){if(action.startsWith("ui.")||action.startsWith("world.")||action.equals("screenshot"))return "input";if(action.startsWith("move."))return "baritone";return Runtime.config().transport.equals("SIMULATE")?"client":"packet";}
 public static String permission(String action){return action.equals("command")?"cheat":action.equals("packet.send")?"hack":"normal";}
 public static Jobs.Step create(String name,JsonObject args){boolean packet=transport(name).equals("packet");if(name.startsWith("container.")&&!Set.of("container.open","container.close").contains(name)||name.startsWith("inventory."))return new ContainerSessions(name,args,packet);
  if(name.equals("batch"))return new Batch(args);
  if(Set.of("player.hold","player.dig","ride.move","wait").contains(name))return new Held(name,args,packet);
  return ()->one(name,args,packet);
 }
 public static JsonObject one(String name,JsonObject a,boolean packet)throws Exception{Minecraft mc=Minecraft.getInstance();if(name.equals("stop")){stop();return Jsons.obj("observed_success",true);}
  if(name.startsWith("ui.")||name.startsWith("world.")||name.equals("screenshot"))return UiActions.execute(name,a);
  if(name.startsWith("packet."))return PacketService.execute(name,a);
  if(mc.player==null||mc.level==null||mc.gameMode==null||mc.getConnection()==null)return Jsons.error("not_in_world");
  switch(name){
   case "move.to" -> {Object provider=Class.forName("baritone.api.BaritoneAPI").getMethod("getProvider").invoke(null);Object b=Class.forName("baritone.api.IBaritoneProvider").getMethod("getPrimaryBaritone").invoke(provider);Object mgr=Class.forName("baritone.api.IBaritone").getMethod("getCommandManager").invoke(b);boolean accepted=Boolean.TRUE.equals(Class.forName("baritone.api.command.manager.ICommandManager").getMethod("execute",String.class).invoke(mgr,"goto "+Jsons.integer(a,"x",0)+" "+Jsons.integer(a,"y",0)+" "+Jsons.integer(a,"z",0)));if(!accepted)return Jsons.error("baritone_rejected");movementOwned=true;return Jsons.obj("delivery","submitted","arrival_confirmed",false);}
   case "move.stop" -> {stop();return Jsons.obj("observed_success",true);}
   case "player.look" -> {float yaw,pitch;if(a.has("yaw")){yaw=(float)Jsons.number(a,"yaw",0);pitch=(float)Jsons.number(a,"pitch",0);}else{Vec3 delta=new Vec3(Jsons.number(a,"x",0),Jsons.number(a,"y",0),Jsons.number(a,"z",0)).subtract(mc.player.getEyePosition());if(delta.lengthSqr()<1e-9)return Jsons.error("look_target_is_eye");yaw=(float)Math.toDegrees(Math.atan2(-delta.x,delta.z));pitch=(float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z)));}if(!Float.isFinite(yaw)||!Float.isFinite(pitch)||pitch < -90||pitch>90)return Jsons.error("invalid_rotation");mc.player.setYRot(yaw);mc.player.setYHeadRot(yaw);mc.player.setXRot(pitch);if(packet)PacketService.sendPacket(new ServerboundMovePlayerPacket.Rot(yaw,pitch,mc.player.onGround()));return Jsons.obj("observed_success",true,"yaw",yaw,"pitch",pitch);}
   case "player.sneak" -> {boolean value=Jsons.bool(a,"value",true);if(oldSneak==null)oldSneak=mc.options.keyShift.isDown();if(!packet)mc.options.keyShift.setDown(value);mc.player.setShiftKeyDown(value);if(packet)PacketService.sendPacket(new ServerboundPlayerCommandPacket(mc.player,value?ServerboundPlayerCommandPacket.Action.PRESS_SHIFT_KEY:ServerboundPlayerCommandPacket.Action.RELEASE_SHIFT_KEY));return Jsons.obj("observed_success",mc.player.isShiftKeyDown()==value,"sneaking",mc.player.isShiftKeyDown());}
   case "player.select" -> {int slot=Jsons.integer(a,"slot",0);if(slot<0||slot>8)return Jsons.error("invalid_hotbar_slot");mc.player.getInventory().selected=slot;if(packet)PacketService.sendPacket(new ServerboundSetCarriedItemPacket(slot));return Jsons.obj("observed_success",true,"selected_slot",slot);}
   case "player.use" -> {InteractionHand hand=hand(a);if(a.has("expected_item")&&!item(mc.player.getItemInHand(hand)).equals(Jsons.str(a,"expected_item","")))return Jsons.error("held_item_changed");if(packet)PacketService.sendPacket(new ServerboundUseItemPacket(hand,0));else mc.gameMode.useItem(mc.player,hand);return submitted();}
   case "block.interact","container.open","block.place" -> {interactBlock(a,packet);return submitted();}
   case "container.close" -> {if(!mc.player.containerMenu.getCarried().isEmpty())return Jsons.error("cursor_not_empty");int id=mc.player.containerMenu.containerId;if(a.has("menu_id")&&Jsons.integer(a,"menu_id",0)!=id)return Jsons.error("menu_changed");if(packet){PacketService.sendPacket(new ServerboundContainerClosePacket(id));mc.player.containerMenu=mc.player.inventoryMenu;mc.setScreen(null);}else mc.player.closeContainer();lastOpenedPosition=null;return Jsons.obj("observed_success",mc.player.containerMenu==mc.player.inventoryMenu);}
   case "entity.interact","entity.attack","ride.mount" -> {Entity e=entity(a);boolean hack=Runtime.config().mode.contains("HACK");if(!hack&&(mc.player.distanceTo(e)>Math.min(6,mc.player.getAttributeValue(ForgeMod.ENTITY_REACH.get()))||!mc.player.hasLineOfSight(e)))return Jsons.error("entity_out_of_reach_or_hidden");if(name.equals("entity.attack")){if(packet)PacketService.sendPacket(ServerboundInteractPacket.createAttackPacket(e,mc.player.isShiftKeyDown()));else mc.gameMode.attack(mc.player,e);}else if(packet)PacketService.sendPacket(ServerboundInteractPacket.createInteractionPacket(e,mc.player.isShiftKeyDown(),hand(a)));else mc.gameMode.interact(mc.player,e,hand(a));return submitted();}
   case "ride.dismount" -> {if(packet)PacketService.sendPacket(new ServerboundPlayerInputPacket(0,0,false,true));else mc.options.keyShift.setDown(true);return submitted();}
   case "chat.send" -> {String text=Jsons.str(a,"text","");if(text.isBlank()||text.length()>256||text.startsWith("/")||text.chars().anyMatch(c->c<32||c==127))return Jsons.error("invalid_chat_message");mc.getConnection().sendChat(text);return submitted();}
   case "command" -> {String text=Jsons.str(a,"command","");if(!text.startsWith("/")||text.length()>256||text.chars().anyMatch(c->c<32||c==127))return Jsons.error("invalid_command");mc.getConnection().sendCommand(text.substring(1));return submitted();}
   default -> {return Jsons.error("unknown_action");}
  }
 }
 public static void interactBlock(JsonObject a,boolean packet){Minecraft mc=Minecraft.getInstance();if(mc.player==null||mc.level==null)throw new IllegalArgumentException("not_in_world");if(mc.player.containerMenu!=mc.player.inventoryMenu)throw new IllegalArgumentException("close_existing_container_first");BlockPos pos=new BlockPos(Jsons.integer(a,"x",0),Jsons.integer(a,"y",0),Jsons.integer(a,"z",0));if(!mc.level.hasChunkAt(pos)||mc.level.isOutsideBuildHeight(pos)||!mc.level.getWorldBorder().isWithinBounds(pos))throw new IllegalArgumentException("target_unloaded_or_outside_world");if(a.has("expected_block")&&!BuiltInRegistries.BLOCK.getKey(mc.level.getBlockState(pos).getBlock()).toString().equals(Jsons.str(a,"expected_block","")))throw new IllegalArgumentException("target_block_changed");Direction face=Direction.valueOf(Jsons.str(a,"face","up").toUpperCase(Locale.ROOT));
  var shape=mc.level.getBlockState(pos).getShape(mc.level,pos);net.minecraft.world.phys.AABB box=shape.isEmpty()?new AABB(0,0,0,1,1,1):shape.bounds();double x=(box.minX+box.maxX)/2,y=(box.minY+box.maxY)/2,z=(box.minZ+box.maxZ)/2;switch(face){case UP->y=box.maxY;case DOWN->y=box.minY;case EAST->x=box.maxX;case WEST->x=box.minX;case SOUTH->z=box.maxZ;case NORTH->z=box.minZ;}
  Vec3 point=new Vec3(pos.getX()+x,pos.getY()+y,pos.getZ()+z);if(!Runtime.config().mode.contains("HACK")){double reach=Math.min(6,mc.player.getAttributeValue(ForgeMod.BLOCK_REACH.get()));if(mc.player.getEyePosition().distanceTo(point)>reach)throw new IllegalArgumentException("block_out_of_reach");BlockHitResult sight=mc.level.clip(new ClipContext(mc.player.getEyePosition(),point.subtract(Vec3.atLowerCornerOf(face.getNormal()).scale(0.01)),ClipContext.Block.OUTLINE,ClipContext.Fluid.NONE,mc.player));if(sight.getType()!=HitResult.Type.BLOCK||!sight.getBlockPos().equals(pos)||sight.getDirection()!=face)throw new IllegalArgumentException("target_face_occluded");}
  if(packet)PacketService.sendPacket(new ServerboundUseItemOnPacket(hand(a),new BlockHitResult(point,face,pos,false),0));else mc.gameMode.useItemOn(mc.player,hand(a),new BlockHitResult(point,face,pos,false));lastOpenedPosition=pos;
 }
 private static Entity entity(JsonObject a){Minecraft mc=Minecraft.getInstance();Entity e=mc.level.getEntity(Jsons.integer(a,"entity_id",-1));if(e==null)throw new IllegalArgumentException("entity_not_loaded");if(a.has("uuid")&&!e.getUUID().toString().equals(Jsons.str(a,"uuid","")))throw new IllegalArgumentException("entity_identity_changed");return e;}
 private static InteractionHand hand(JsonObject a){String h=Jsons.str(a,"hand","main");if(!Set.of("main","off").contains(h))throw new IllegalArgumentException("invalid_hand");return h.equals("off")?InteractionHand.OFF_HAND:InteractionHand.MAIN_HAND;}
 private static String item(ItemStack s){return BuiltInRegistries.ITEM.getKey(s.getItem()).toString();}
 private static JsonObject submitted(){return Jsons.obj("delivery","submitted","server_acceptance_confirmed",false);}
 public static void stop(){Minecraft mc=Minecraft.getInstance();if(movementOwned)try{Object p=Class.forName("baritone.api.BaritoneAPI").getMethod("getProvider").invoke(null);Object b=Class.forName("baritone.api.IBaritoneProvider").getMethod("getPrimaryBaritone").invoke(p);Object path=Class.forName("baritone.api.IBaritone").getMethod("getPathingBehavior").invoke(b);Class.forName("baritone.api.behavior.IPathingBehavior").getMethod("cancelEverything").invoke(path);}catch(Exception ignored){}movementOwned=false;if(oldSneak!=null){mc.options.keyShift.setDown(oldSneak);if(mc.player!=null){mc.player.setShiftKeyDown(oldSneak);if(mc.getConnection()!=null)PacketService.sendPacket(new ServerboundPlayerCommandPacket(mc.player,oldSneak?ServerboundPlayerCommandPacket.Action.PRESS_SHIFT_KEY:ServerboundPlayerCommandPacket.Action.RELEASE_SHIFT_KEY));}oldSneak=null;}mc.options.keyAttack.setDown(false);mc.options.keyUse.setDown(false);if(mc.player!=null&&mc.gameMode!=null&&mc.player.isUsingItem())mc.gameMode.releaseUsingItem(mc.player);}
 private static final class Held implements Jobs.Step,Jobs.Cleanup {
  final String name;final JsonObject a;final boolean packet;int ticks;boolean initialized,oldUse,oldAttack;BlockPos pos;Direction face;float progress;boolean stopSent;
  Held(String n,JsonObject a,boolean p){name=n;this.a=a.deepCopy();packet=p;}
  public JsonObject tick()throws Exception{Minecraft mc=Minecraft.getInstance();if(mc.player==null||mc.level==null)return Jsons.error("not_in_world");int duration=Jsons.integer(a,"ticks",40);if(duration<1||duration>1200)return Jsons.error("duration_out_of_range_1_1200");if(name.equals("wait")){boolean met=condition(Jsons.object(a,"condition"));if(met)return Jsons.obj("observed_success",true);if(ticks++>=duration)return Jsons.error("condition_timeout");return Jsons.obj("pending",true);}
   if(name.equals("ride.move")){if(!mc.player.isPassenger())return Jsons.error("not_riding");float forward=(float)Math.max(-1,Math.min(1,Jsons.number(a,"forward",1))),strafe=(float)Math.max(-1,Math.min(1,Jsons.number(a,"strafe",0)));if(ticks++>=duration)return Jsons.obj("delivery","submitted","ticks",ticks);mc.player.input.forwardImpulse=forward;mc.player.input.leftImpulse=strafe;mc.player.input.jumping=Jsons.bool(a,"jump",false);if(packet)PacketService.sendPacket(new ServerboundPlayerInputPacket(strafe,forward,Jsons.bool(a,"jump",false),false));else{mc.options.keyUp.setDown(forward>0);mc.options.keyDown.setDown(forward<0);}return Jsons.obj("pending",true);}
   if(name.equals("player.hold")){if(!initialized){initialized=true;oldUse=mc.options.keyUse.isDown();oldAttack=mc.options.keyAttack.isDown();if(oldUse||oldAttack)return Jsons.error("user_input_already_active");if(Jsons.str(a,"button","right").equals("right")){if(packet)PacketService.sendPacket(new ServerboundUseItemPacket(hand(a),0));else{mc.options.keyUse.setDown(true);mc.gameMode.useItem(mc.player,hand(a));}}else if(!packet)mc.options.keyAttack.setDown(true);else if(a.has("entity_id"))PacketService.sendPacket(ServerboundInteractPacket.createAttackPacket(entity(a),mc.player.isShiftKeyDown()));else return Jsons.error("packet_left_hold_requires_entity_or_player_dig");}if(ticks++>=duration)return Jsons.obj("delivery","submitted","ticks",ticks);return Jsons.obj("pending",true);}
   if(!initialized){initialized=true;pos=new BlockPos(Jsons.integer(a,"x",0),Jsons.integer(a,"y",0),Jsons.integer(a,"z",0));face=Direction.valueOf(Jsons.str(a,"face","up").toUpperCase(Locale.ROOT));if(!mc.level.hasChunkAt(pos))return Jsons.error("target_unloaded");if(mc.player.isSpectator())return Jsons.error("spectator_cannot_break");if(!Runtime.config().mode.contains("HACK")&&mc.player.getEyePosition().distanceTo(Vec3.atCenterOf(pos))>Math.min(6,mc.player.getAttributeValue(ForgeMod.BLOCK_REACH.get())))return Jsons.error("target_out_of_reach");if(a.has("expected_block")&&!BuiltInRegistries.BLOCK.getKey(mc.level.getBlockState(pos).getBlock()).toString().equals(Jsons.str(a,"expected_block","")))return Jsons.error("block_changed");if(!Runtime.config().mode.contains("HACK")){var shape=mc.level.getBlockState(pos).getShape(mc.level,pos);if(shape.isEmpty())return Jsons.error("block_has_no_target_shape");Vec3 target=shape.bounds().move(pos).getCenter();BlockHitResult hit=mc.level.clip(new ClipContext(mc.player.getEyePosition(),target,ClipContext.Block.OUTLINE,ClipContext.Fluid.NONE,mc.player));if(hit.getType()!=HitResult.Type.BLOCK||!hit.getBlockPos().equals(pos))return Jsons.error("dig_target_occluded");face=hit.getDirection();}if(packet)PacketService.sendPacket(new ServerboundPlayerActionPacket(ServerboundPlayerActionPacket.Action.START_DESTROY_BLOCK,pos,face));else mc.gameMode.startDestroyBlock(pos,face);}
   if(mc.level.getBlockState(pos).isAir())return Jsons.obj("observed_success",true,"block_removed",true);if(ticks++>duration)return Jsons.error("dig_timeout");if(packet){if(!stopSent){progress+=mc.level.getBlockState(pos).getDestroyProgress(mc.player,mc.level,pos);if(progress>=1||mc.player.isCreative()){PacketService.sendPacket(new ServerboundPlayerActionPacket(ServerboundPlayerActionPacket.Action.STOP_DESTROY_BLOCK,pos,face));stopSent=true;}}}else mc.gameMode.continueDestroyBlock(pos,face);return Jsons.obj("pending",true,"ticks",ticks);
  }
  public void cleanup(){Minecraft mc=Minecraft.getInstance();if(mc.player!=null&&mc.getConnection()!=null){if(name.equals("player.hold")){if(packet)PacketService.sendPacket(new ServerboundPlayerActionPacket(ServerboundPlayerActionPacket.Action.RELEASE_USE_ITEM,BlockPos.ZERO,Direction.DOWN));else if(mc.gameMode!=null)mc.gameMode.releaseUsingItem(mc.player);}if(name.equals("player.dig")&&pos!=null)PacketService.sendPacket(new ServerboundPlayerActionPacket(ServerboundPlayerActionPacket.Action.ABORT_DESTROY_BLOCK,pos,face));if(name.equals("ride.move")){mc.player.input.forwardImpulse=0;mc.player.input.leftImpulse=0;mc.player.input.jumping=false;PacketService.sendPacket(new ServerboundPlayerInputPacket(0,0,false,false));}}
   if(name.equals("player.hold")&&!packet){mc.options.keyUse.setDown(oldUse);mc.options.keyAttack.setDown(oldAttack);}if(name.equals("ride.move")){mc.options.keyUp.setDown(false);mc.options.keyDown.setDown(false);}}
 }
 public static boolean condition(JsonObject c){Minecraft mc=Minecraft.getInstance();if(mc.player==null||mc.level==null)return false;return switch(Jsons.str(c,"kind","")){case "position"->mc.player.position().distanceTo(new Vec3(Jsons.number(c,"x",0),Jsons.number(c,"y",0),Jsons.number(c,"z",0)))<=Jsons.number(c,"tolerance",1);case "menu"->mc.player.containerMenu.getClass().getName().contains(Jsons.str(c,"class",""));case "inventory"->{int count=0;for(ItemStack s:mc.player.getInventory().items)if(item(s).equals(Jsons.str(c,"item_id","")))count+=s.getCount();yield count>=Jsons.integer(c,"min_count",1);}case "block"->BuiltInRegistries.BLOCK.getKey(mc.level.getBlockState(new BlockPos(Jsons.integer(c,"x",0),Jsons.integer(c,"y",0),Jsons.integer(c,"z",0))).getBlock()).toString().equals(Jsons.str(c,"block_id",""));default->false;};}
 private static final class Batch implements Jobs.Step,Jobs.Cleanup {final JsonArray steps;int index;Jobs.Step current;JsonArray results=new JsonArray();Batch(JsonObject a){steps=Jsons.array(a,"steps").deepCopy();if(steps.isEmpty()||steps.size()>32)throw new IllegalArgumentException("invalid_batch_size");for(JsonElement e:steps){String action=Jsons.str(e.getAsJsonObject(),"action","");if(action.equals("batch")||action.equals("stop"))throw new IllegalArgumentException("invalid_batch_child");if(!Policy.allowed(Runtime.config().mode,Runtime.config().transport,transport(action),permission(action)))throw new IllegalArgumentException("batch_policy_denied");}}
  public JsonObject tick()throws Exception{if(current==null){JsonObject s=steps.get(index).getAsJsonObject();current=create(Jsons.str(s,"action",""),Jsons.object(s,"arguments"));}JsonObject r=current.tick();if(r.has("pending"))return Jsons.obj("pending",true,"step",index,"progress",r);if(r.has("error"))return Jsons.obj("error","batch_step_failed","step",index,"detail",r,"completed",results);if(current instanceof Jobs.Cleanup c)c.cleanup();current=null;results.add(r);index++;return index==steps.size()?Jsons.obj("delivery","submitted","steps",results):Jsons.obj("pending",true,"step",index);}
  public void cleanup(){if(current instanceof Jobs.Cleanup c)c.cleanup();}
 }
 private Actions(){}
}
